using FlotixPlatform.API.Analytics.Domain.Model.Commands;

namespace FlotixPlatform.API.Analytics.Domain.Model.Aggregates;

/// <summary>
///     Represents a fleet report generated by an owner with its filter parameters.
/// </summary>
/// <remarks>
///     This aggregate root is created from a CreateReportCommand and is immutable afterwards.
///     Audit timestamps (CreatedAt, UpdatedAt) are managed by the persistence layer.
/// </remarks>
public partial class Report
{
    /// <summary>
    ///     Protected parameterless constructor for EF Core.
    /// </summary>
    protected Report()
    {
        ReportType = string.Empty;
        FilterParams = [];
    }

    /// <summary>
    ///     Creates a new Report from a creation command.
    /// </summary>
    /// <param name="command">The CreateReportCommand command</param>
    /// <exception cref="ArgumentNullException">Thrown when the command is null.</exception>
    /// <exception cref="ArgumentException">Thrown when the command contains invalid values.</exception>
    public Report(CreateReportCommand command)
    {
        ArgumentNullException.ThrowIfNull(command);
        ArgumentOutOfRangeException.ThrowIfLessThan(command.OwnerId, 1);
        ArgumentException.ThrowIfNullOrWhiteSpace(command.ReportType);
        ArgumentOutOfRangeException.ThrowIfGreaterThan(command.ReportType.Length, 120);
        ArgumentNullException.ThrowIfNull(command.FilterParams);
        ArgumentOutOfRangeException.ThrowIfGreaterThan(command.FilterParams.Count, 10);

        OwnerId = command.OwnerId;
        ReportType = command.ReportType;
        FilterParams = command.FilterParams;
        GeneratedAt = DateTimeOffset.UtcNow;
    }

    /// <summary>
    ///     Gets the server-generated identifier for this report.
    /// </summary>
    public int Id { get; private set; }

    /// <summary>
    ///     Gets the identifier of the owner user.
    /// </summary>
    public int OwnerId { get; private set; }

    /// <summary>
    ///     Gets the type of the report (e.g. Reporte de incidencias).
    /// </summary>
    public string ReportType { get; private set; }

    /// <summary>
    ///     Gets the filters applied to the report.
    /// </summary>
    public Dictionary<string, string> FilterParams { get; private set; }

    /// <summary>
    ///     Gets the moment the report was generated.
    /// </summary>
    public DateTimeOffset GeneratedAt { get; private set; }
}
